-- Section 6 — Mixed / Challenge Tasks
-- Task 36:  For each state, find the total number of customers AND the total revenue generated by those customers.
select state, count(DISTINCT cus.customer_id) as 'Total No of Customer', SUM(ord_itm.quantity * ord_itm.list_price * (1 - ord_itm.discount)) as 'Total Revenue' from sales.customers as cus
join sales.orders as ord
on cus.customer_id = ord.customer_id
join sales.order_items as ord_itm
on ord.order_id = ord_itm.order_id
group by cus.state
-- Task 37:  Rank all products by price within each category.
select *, ROW_NUMBER() over (partition by category_id order by list_price desc) from production.products
-- Hint: Use ROW_NUMBER() or RANK() with PARTITION BY category_id.
-- Task 38:  Find the month-wise order count and total revenue for the year 2017.
select Month(ord.order_date) as 'Month', count(DISTINCT ord.order_id) as 'No of orders', SUM(ord_itm.quantity * ord_itm.list_price * (1 - ord_itm.discount)) as 'Total Revenue' from sales.orders as ord
join sales.order_items as ord_itm
on ord.order_id = ord_itm.order_id
where YEAR(ord.order_date) = 2017
group by Month(ord.order_date)
-- Task 39:  List each store's best-selling product (by quantity sold).
With BestSellingProductByEachStore as (
select stre.store_id,stre.store_name, prd.product_id, prd.product_name,
sum(stk.quantity) 'Total Quantity Sold',
ROW_NUMBER() over(partition by stre.store_id order by sum(stk.quantity) desc) RankProduct
from production.stocks as stk
join sales.stores as stre
on stk.store_id = stre.store_id
join production.products as prd
on stk.product_id = prd.product_id
join sales.order_items as ord_itm
on prd.product_id = ord_itm.product_id
group by stre.store_id,stre.store_name, prd.product_id, prd.product_name
)
select * from BestSellingProductByEachStore where RankProduct = 1
-- Task 40:  Write a query to produce a report showing: store name, staff name, number of orders, and total revenue
-- grouped by store and staff member, sorted by revenue descending.
select stf.first_name + ' ' + stf.last_name as 'Staff Name', stre.store_name as 'Store Name', COUNT(distinct ord.order_id) 'No of Orders', SUM(ord_itm.quantity * ord_itm.list_price * (1 - ord_itm.discount)) Total_Revenue from sales.stores as stre
join sales.staffs as stf
on stre.store_id = stf.store_id
join sales.orders as ord
on ord.staff_id = stf.staff_id
join sales.order_items as ord_itm
on ord.order_id = ord_itm.order_id
group by stf.first_name + ' ' + stf.last_name, stre.store_name
order by Total_Revenue desc